action.code:
for (int i = size / 2 - 1; i >= 0; --i) {
    int parent = i;
    while (true) {
        int leftChild = 2 * parent + 1;
        int rightChild = 2 * parent + 2;
        int smallest = parent;

        if (leftChild < size && arr[leftChild] < arr[smallest]) {
            smallest = leftChild;
        }
        if (rightChild < size && arr[rightChild] < arr[smallest]) {
            smallest = rightChild;
        }

        if (smallest != parent) {
            std::swap(arr[parent], arr[smallest]);
            parent = smallest;
        } else {
            break;
        }
    }
}

