            smallest = leftChild;
        }
        if (rightChild < size && arr[rightChild] < arr[smallest]) {
            smallest = rightChild;
        }

        if (smallest != parent) {
            std::swap(arr[parent], arr[smallest]);
            parent = smallest;
        } else {
            break;
        }
    }
}

